export type ListVariant = 'singly' | 'doubly' | 'circular' | 'doubly-circular';
export type LinkedNode = { id: string; val: number; nextId: string | null; prevId: string | null };
export type LinkedListModel = { variant: ListVariant; nodes: LinkedNode[]; headId: string | null; tailId: string | null; nextId: number };
export type CircularQueueModel = { slots: Array<string | null>; front: number; size: number };
export type LinkedQueueNode = { id: string; value: string; nextId: string | null };
export type LinkedQueueModel = { nodes: LinkedQueueNode[]; frontId: string | null; rearId: string | null; nextId: number };
export type HeapItem = { val: number; priority: number; label: string };
export type BSTNode = { val: number; left?: BSTNode; right?: BSTNode };
export type HashEntry = { key: string; val: string };
export type BfsStep = { current: string; queue: string[]; visited: string[]; inspectedEdges: Array<{ from: string; to: string }> };

export const LIST_VARIANTS: readonly ListVariant[];
export function arrayInsertAt(values: number[], index: number, value: number): number[];
export function arrayDeleteAt(values: number[], index: number): { values: number[]; removed: number };
export function arrayUpdateAt(values: number[], index: number, value: number): { values: number[]; previous: number };
export function arrayLinearSearch(values: number[], target: number): { index: number; comparisons: number };
export function parseArrayValues(text: string, maxLength?: number): { valid: boolean; values: number[]; error: string | null };
export function mergeSortedArrays(left: number[], right: number[]): number[];
export function calculateArrayAddress(baseAddress: number, elementSize: number, index: number): number;
export function createLinkedList(values?: number[], variant?: ListVariant): LinkedListModel;
export function getLinkedListNodes(list: LinkedListModel): LinkedNode[];
export function insertLinkedListAt(list: LinkedListModel, index: number, value: number): LinkedListModel;
export function deleteLinkedListAt(list: LinkedListModel, index: number): { list: LinkedListModel; removed: LinkedNode };
export function linkedListInvariantErrors(list: LinkedListModel): string[];
export function linkedListSearch(list: LinkedListModel, target: number): { index: number; visited: number };
export function stackPush<T>(stack: T[], item: T): T[];
export function stackPop<T>(stack: T[]): { stack: T[]; item: T | null };
export function createCircularQueue(capacity?: number, values?: string[]): CircularQueueModel;
export function circularQueueValues(queue: CircularQueueModel): Array<string | null>;
export function circularQueueEnqueue(queue: CircularQueueModel, value: string): { queue: CircularQueueModel; accepted: boolean };
export function circularQueueDequeue(queue: CircularQueueModel): { queue: CircularQueueModel; item: string | null };
export function createLinkedQueue(values?: string[]): LinkedQueueModel;
export function linkedQueueValues(queue: LinkedQueueModel): string[];
export function linkedQueueEnqueue(queue: LinkedQueueModel, value: string): LinkedQueueModel;
export function linkedQueueDequeue(queue: LinkedQueueModel): { queue: LinkedQueueModel; item: string | null };
export function linkedQueueInvariantErrors(queue: LinkedQueueModel): string[];
export function heapInsert(heap: HeapItem[], item: HeapItem): HeapItem[];
export function heapExtractMin(heap: HeapItem[]): { heap: HeapItem[]; item: HeapItem | null };
export function isMinHeap(heap: HeapItem[]): boolean;
export function insertBST(node: BSTNode | undefined, value: number): BSTNode;
export function traverseBST(node: BSTNode | undefined, order?: 'in-order' | 'pre-order' | 'post-order', result?: number[]): number[];
export function searchBST(node: BSTNode | undefined, value: number): { found: boolean; visited: number[] };
export function teachingHash(key: string, bucketCount?: number): number;
export function hashPut(buckets: HashEntry[][], key: string, value: string): { buckets: HashEntry[][]; bucketIndex: number; updated: boolean };
export function createTeachingHashTable(entries?: HashEntry[], bucketCount?: number): HashEntry[][];
export function hashGet(buckets: HashEntry[][], key: string): { bucketIndex: number; entry: HashEntry | null };
export function hashDelete(buckets: HashEntry[][], key: string): { buckets: HashEntry[][]; bucketIndex: number; removed: boolean };
export function buildBfsTrace(nodes: Array<{ id: string }>, edges: Array<{ from: string; to: string }>, start: string): BfsStep[];
